(()=>{const added=[{"id":"daily-2026-10-12-r01-q01","module":"C++","type":"概念题","title":"为什么构造函数中通常不能调用 shared_from_this？","prompt":"为什么构造函数中通常不能调用 shared_from_this？","promptMarkdown":"为什么构造函数中通常不能调用 shared_from_this？","answer":["enable_shared_from_this 的内部弱引用要等适当的 shared_ptr 建立拥有关系后才能使用；构造过程通常尚未建立，调用 shared_from_this 会抛 bad_weak_ptr。应在工厂建立共享所有权后进行需要它的初始化。"],"answerMarkdown":"enable_shared_from_this 的内部弱引用要等适当的 shared_ptr 建立拥有关系后才能使用；构造过程通常尚未建立，调用 shared_from_this 会抛 bad_weak_ptr。应在工厂建立共享所有权后进行需要它的初始化。\n\n**易错点：**不要为同一个裸指针另建 shared_ptr 控制块。\n\n**下一轮强化：**构造后初始化与引用环","pitfalls":["不要为同一个裸指针另建 shared_ptr 控制块。"],"follow":"构造后初始化与引用环","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":1,"sourceQuestion":1,"sourceRoundTitle":"shared_from_this 与异步对象寿命"},{"id":"daily-2026-10-12-r01-q02","module":"C++","type":"概念题","title":"weak_ptr::lock 成功是否证明会话有效且线程安全？","prompt":"weak_ptr::lock 成功是否证明会话有效且线程安全？","promptMarkdown":"weak_ptr::lock 成功是否证明会话有效且线程安全？","answer":["lock 成功只保证得到强引用并在其存活期间保持对象寿命，不保护成员，也不证明该对象仍属于当前会话。状态修改应遵守 Reactor 归属或锁，并校验代际。"],"answerMarkdown":"lock 成功只保证得到强引用并在其存活期间保持对象寿命，不保护成员，也不证明该对象仍属于当前会话。状态修改应遵守 Reactor 归属或锁，并校验代际。\n\n**易错点：**对象存活不等于业务有效。\n\n**下一轮强化：**构造后初始化与引用环","pitfalls":["对象存活不等于业务有效。"],"follow":"构造后初始化与引用环","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":1,"sourceQuestion":2,"sourceRoundTitle":"shared_from_this 与异步对象寿命"},{"id":"daily-2026-10-12-r01-q03","module":"C++","type":"场景题","title":"异步回调捕获 this 后对象已析构，怎么修复？","prompt":"异步回调捕获 this 后对象已析构，怎么修复？","promptMarkdown":"异步回调捕获 this 后对象已析构，怎么修复？","answer":["关联对象创建销毁与任务执行，使用 ASan 和最小延迟复现。改为 weak_ptr 捕获并在消费线程 lock；如果任务必须延长寿命才用强引用，同时防止引用环和无限保留。"],"answerMarkdown":"关联对象创建销毁与任务执行，使用 ASan 和最小延迟复现。改为 weak_ptr 捕获并在消费线程 lock；如果任务必须延长寿命才用强引用，同时防止引用环和无限保留。\n\n**易错点：**捕获裸 this 不延长寿命。\n\n**下一轮强化：**构造后初始化与引用环","pitfalls":["捕获裸 this 不延长寿命。"],"follow":"构造后初始化与引用环","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":1,"sourceQuestion":3,"sourceRoundTitle":"shared_from_this 与异步对象寿命"},{"id":"daily-2026-10-12-r01-q04","module":"C++","type":"代码题","title":"实现工厂构造 Session，再生成 weak_ptr 回调；对象销毁后回调拒绝执行。","prompt":"实现工厂构造 Session，再生成 weak_ptr 回调；对象销毁后回调拒绝执行。","promptMarkdown":"实现工厂构造 Session，再生成 weak_ptr 回调；对象销毁后回调拒绝执行。","answer":["见代码。factory 返回 shared_ptr 后才创建回调，回调是单线程示例，不提供线程安全或代际校验。"],"answerMarkdown":"见代码。factory 返回 shared_ptr 后才创建回调，回调是单线程示例，不提供线程安全或代际校验。\n\n**易错点：**factory 也不保证成员并发安全。\n\n```cpp\n#include <cassert>\n#include <functional>\n#include <memory>\nclass Session:public std::enable_shared_from_this<Session>{\n    int value_=0;\npublic:\n    static std::shared_ptr<Session> create(){return std::make_shared<Session>();}\n    std::function<bool()> callback(){\n        auto weak=weak_from_this();\n        return [weak]{auto live=weak.lock();if(!live)return false;++live->value_;return true;};\n    }\n    int value() const{return value_;}\n};\nint main(){auto s=Session::create();auto f=s->callback();assert(f()&&s->value()==1);s.reset();assert(!f());}\n\n```\n\n**复杂度与边界：**O(1) 时间/空间，不含分配器成本。单线程调用，真实计数防溢出；未验证跨线程取消。\n\n**下一轮强化：**构造后初始化与引用环\n\n代码通过 C++17 严格警告编译及所附断言。","pitfalls":["factory 也不保证成员并发安全。"],"follow":"构造后初始化与引用环","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":1,"sourceQuestion":4,"sourceRoundTitle":"shared_from_this 与异步对象寿命"},{"id":"daily-2026-10-12-r01-q05","module":"项目追问","type":"场景题","title":"IM 回调的对象寿命、取消状态和会话 generation 如何共同校验？","prompt":"IM 回调的对象寿命、取消状态和会话 generation 如何共同校验？","promptMarkdown":"IM 回调的对象寿命、取消状态和会话 generation 如何共同校验？","answer":["建议工作线程计算结果，回到 Reactor 后检查对象、取消和 generation，再修改状态；资源销毁前仍要等任务退出，取消标志不能替代 join。"],"answerMarkdown":"建议工作线程计算结果，回到 Reactor 后检查对象、取消和 generation，再修改状态；资源销毁前仍要等任务退出，取消标志不能替代 join。\n\n**易错点：**检查与更新的取消窗口需明确。\n\n**下一轮强化：**构造后初始化与引用环","pitfalls":["检查与更新的取消窗口需明确。"],"follow":"构造后初始化与引用环","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":1,"sourceQuestion":5,"sourceRoundTitle":"shared_from_this 与异步对象寿命"},{"id":"daily-2026-10-12-r02-q01","module":"C++","type":"概念题","title":"T&& 什么时候是转发引用，什么时候只是右值引用？","prompt":"T&& 什么时候是转发引用，什么时候只是右值引用？","promptMarkdown":"T&& 什么时候是转发引用，什么时候只是右值引用？","answer":["模板推导的无 cv 限定 T&& 常是转发引用；固定类型 X&& 是普通右值引用。引用折叠中只要参与折叠的是左值引用，结果通常折叠为左值引用。"],"answerMarkdown":"模板推导的无 cv 限定 T&& 常是转发引用；固定类型 X&& 是普通右值引用。引用折叠中只要参与折叠的是左值引用，结果通常折叠为左值引用。\n\n**易错点：**const T&& 不是同样的转发引用模式。\n\n**下一轮强化：**lambda 捕获与移动型任务","pitfalls":["const T&& 不是同样的转发引用模式。"],"follow":"lambda 捕获与移动型任务","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":2,"sourceQuestion":1,"sourceRoundTitle":"完美转发与引用折叠"},{"id":"daily-2026-10-12-r02-q02","module":"C++","type":"概念题","title":"std::forward 与 std::move 应如何选择？","prompt":"std::forward 与 std::move 应如何选择？","promptMarkdown":"std::forward 与 std::move 应如何选择？","answer":["move 无条件转换为相应右值引用；forward<T> 按推导类型保留调用者值类别。两者都不直接执行资源转移，实际行为取决于重载。"],"answerMarkdown":"move 无条件转换为相应右值引用；forward<T> 按推导类型保留调用者值类别。两者都不直接执行资源转移，实际行为取决于重载。\n\n**易错点：**forward 需使用正确的模板类型。\n\n**下一轮强化：**lambda 捕获与移动型任务","pitfalls":["forward 需使用正确的模板类型。"],"follow":"lambda 捕获与移动型任务","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":2,"sourceQuestion":2,"sourceRoundTitle":"完美转发与引用折叠"},{"id":"daily-2026-10-12-r02-q03","module":"C++","type":"场景题","title":"通用包装器把所有参数 move，调用者对象意外被消耗，如何定位？","prompt":"通用包装器把所有参数 move，调用者对象意外被消耗，如何定位？","promptMarkdown":"通用包装器把所有参数 move，调用者对象意外被消耗，如何定位？","answer":["检查包装器是否对左值也 std::move，关注调用后状态与重载日志；修复为 forward，并明确哪些接口有意消费所有权。不要把模板推导当成自动解决寿命。"],"answerMarkdown":"检查包装器是否对左值也 std::move，关注调用后状态与重载日志；修复为 forward，并明确哪些接口有意消费所有权。不要把模板推导当成自动解决寿命。\n\n**易错点：**意外移动可能不会立即崩溃。\n\n**下一轮强化：**lambda 捕获与移动型任务","pitfalls":["意外移动可能不会立即崩溃。"],"follow":"lambda 捕获与移动型任务","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":2,"sourceQuestion":3,"sourceRoundTitle":"完美转发与引用折叠"},{"id":"daily-2026-10-12-r02-q04","module":"C++","type":"代码题","title":"实现包装器，转发参数并保留被调用函数的引用返回类型。","prompt":"实现包装器，转发参数并保留被调用函数的引用返回类型。","promptMarkdown":"实现包装器，转发参数并保留被调用函数的引用返回类型。","answer":["见代码，decltype(auto) 保留引用返回；测试左值与右值重载、可修改的引用返回。"],"answerMarkdown":"见代码，decltype(auto) 保留引用返回；测试左值与右值重载、可修改的引用返回。\n\n**易错点：**返回引用可能引用短命对象。\n\n```cpp\n#include <cassert>\n#include <utility>\nint kind(int&){return 1;}int kind(int&&){return 2;}\ntemplate<class F,class T>decltype(auto) call(F&& f,T&& x){return std::forward<F>(f)(std::forward<T>(x));}\nint main(){\n    int n=3;auto classify=[](auto&& x){return kind(std::forward<decltype(x)>(x));};\n    assert(call(classify,n)==1);assert(call(classify,3)==2);\n    auto identity=[](int& x)->int&{return x;};call(identity,n)=7;assert(n==7);\n}\n\n```\n\n**复杂度与边界：**包装本身 O(1)，被调用函数成本另计。调用同步完成；不实现异步存储。\n\n**下一轮强化：**lambda 捕获与移动型任务\n\n代码通过 C++17 严格警告编译及所附断言。","pitfalls":["返回引用可能引用短命对象。"],"follow":"lambda 捕获与移动型任务","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":2,"sourceQuestion":4,"sourceRoundTitle":"完美转发与引用折叠"},{"id":"daily-2026-10-12-r02-q05","module":"项目追问","type":"场景题","title":"IM 通用任务封装应保留引用还是拥有参数？","prompt":"IM 通用任务封装应保留引用还是拥有参数？","promptMarkdown":"IM 通用任务封装应保留引用还是拥有参数？","answer":["异步队列通常需要拥有参数或明确共享寿命；完美转发只影响构造时值类别，不能让保存在任务中的引用自动存活到执行。"],"answerMarkdown":"异步队列通常需要拥有参数或明确共享寿命；完美转发只影响构造时值类别，不能让保存在任务中的引用自动存活到执行。\n\n**易错点：**引用封装必须有寿命契约。\n\n**下一轮强化：**lambda 捕获与移动型任务","pitfalls":["引用封装必须有寿命契约。"],"follow":"lambda 捕获与移动型任务","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":2,"sourceQuestion":5,"sourceRoundTitle":"完美转发与引用折叠"},{"id":"daily-2026-10-12-r03-q01","module":"C++","type":"概念题","title":"reserve、resize、shrink_to_fit 分别影响什么？","prompt":"reserve、resize、shrink_to_fit 分别影响什么？","promptMarkdown":"reserve、resize、shrink_to_fit 分别影响什么？","answer":["reserve 提高可用容量而不改变有效元素数；resize 改变 size，增加时构造新元素；shrink_to_fit 是非强制请求，不能保证容量等于 size。"],"answerMarkdown":"reserve 提高可用容量而不改变有效元素数；resize 改变 size，增加时构造新元素；shrink_to_fit 是非强制请求，不能保证容量等于 size。\n\n**易错点：**容量不是元素数。\n\n**下一轮强化：**扩容、noexcept 与迭代器失效","pitfalls":["容量不是元素数。"],"follow":"扩容、noexcept 与迭代器失效","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":3,"sourceQuestion":1,"sourceRoundTitle":"vector 容量与构造语义"},{"id":"daily-2026-10-12-r03-q02","module":"C++","type":"概念题","title":"push_back 与 emplace_back 一定有性能差距吗？","prompt":"push_back 与 emplace_back 一定有性能差距吗？","promptMarkdown":"push_back 与 emplace_back 一定有性能差距吗？","answer":["emplace_back 用参数直接构造元素，某些场景减少临时对象，但已存在对象仍可能复制或移动；扩容、分配和构造成本常更关键。需测量，不能套用一定更快。"],"answerMarkdown":"emplace_back 用参数直接构造元素，某些场景减少临时对象，但已存在对象仍可能复制或移动；扩容、分配和构造成本常更关键。需测量，不能套用一定更快。\n\n**易错点：**原地构造仍可能扩容搬迁旧元素。\n\n**下一轮强化：**扩容、noexcept 与迭代器失效","pitfalls":["原地构造仍可能扩容搬迁旧元素。"],"follow":"扩容、noexcept 与迭代器失效","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":3,"sourceQuestion":2,"sourceRoundTitle":"vector 容量与构造语义"},{"id":"daily-2026-10-12-r03-q03","module":"C++","type":"场景题","title":"reserve(100) 后直接写 v[0]，为什么仍是错误？","prompt":"reserve(100) 后直接写 v[0]，为什么仍是错误？","promptMarkdown":"reserve(100) 后直接写 v[0]，为什么仍是错误？","answer":["capacity 表示存储能力，不代表该位置已有有效元素；operator[] 必须满足索引小于 size。用 ASan 辅助但不能依赖它必定发现容量内的无效访问。"],"answerMarkdown":"capacity 表示存储能力，不代表该位置已有有效元素；operator[] 必须满足索引小于 size。用 ASan 辅助但不能依赖它必定发现容量内的无效访问。\n\n**易错点：**未崩溃不代表代码合法。\n\n**下一轮强化：**扩容、noexcept 与迭代器失效","pitfalls":["未崩溃不代表代码合法。"],"follow":"扩容、noexcept 与迭代器失效","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":3,"sourceQuestion":3,"sourceRoundTitle":"vector 容量与构造语义"},{"id":"daily-2026-10-12-r03-q04","module":"C++","type":"代码题","title":"演示 reserve 不创建元素、resize 创建元素，并验证 emplacement 的有效结果。","prompt":"演示 reserve 不创建元素、resize 创建元素，并验证 emplacement 的有效结果。","promptMarkdown":"演示 reserve 不创建元素、resize 创建元素，并验证 emplacement 的有效结果。","answer":["见代码，不实际执行越界访问；用 at 验证 size 边界，并检查有效内容。"],"answerMarkdown":"见代码，不实际执行越界访问；用 at 验证 size 边界，并检查有效内容。\n\n**易错点：**at 只检查有效范围。\n\n```cpp\n#include <cassert>\n#include <stdexcept>\n#include <string>\n#include <vector>\nint main(){\n    std::vector<std::string> v;v.reserve(4);assert(v.empty()&&v.capacity()>=4);\n    bool bad=false;try{v.at(0);}catch(const std::out_of_range&){bad=true;}assert(bad);\n    v.resize(2);assert(v.size()==2&&v[0].empty());v.emplace_back(3,'x');\n    assert(v.size()==3&&v.back()==\"xxx\");\n}\n\n```\n\n**复杂度与边界：**容量操作可能分配；本例数量固定。一般 reserve/resize 与元素数线性相关，emplace_back 摊还 O(1) 加构造成本。\n\n**下一轮强化：**扩容、noexcept 与迭代器失效\n\n代码通过 C++17 严格警告编译及所附断言。","pitfalls":["at 只检查有效范围。"],"follow":"扩容、noexcept 与迭代器失效","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":3,"sourceQuestion":4,"sourceRoundTitle":"vector 容量与构造语义"},{"id":"daily-2026-10-12-r03-q05","module":"项目追问","type":"场景题","title":"历史消息批量装载怎样估计容量而不浪费过多内存？","prompt":"历史消息批量装载怎样估计容量而不浪费过多内存？","promptMarkdown":"历史消息批量装载怎样估计容量而不浪费过多内存？","answer":["建议依据有上限的页大小 reserve，避免对不可信 count 无界分配；批次结束可复用合理容量，持续保留峰值容量需结合节点内存预算判断。"],"answerMarkdown":"建议依据有上限的页大小 reserve，避免对不可信 count 无界分配；批次结束可复用合理容量，持续保留峰值容量需结合节点内存预算判断。\n\n**易错点：**频繁 shrink 也可能增加分配成本。\n\n**下一轮强化：**扩容、noexcept 与迭代器失效","pitfalls":["频繁 shrink 也可能增加分配成本。"],"follow":"扩容、noexcept 与迭代器失效","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":3,"sourceQuestion":5,"sourceRoundTitle":"vector 容量与构造语义"},{"id":"daily-2026-10-12-r04-q01","module":"Linux","type":"概念题","title":"timerfd 怎样与 epoll 配合，read 返回的数据是什么？","prompt":"timerfd 怎样与 epoll 配合，read 返回的数据是什么？","promptMarkdown":"timerfd 怎样与 epoll 配合，read 返回的数据是什么？","answer":["timerfd 将定时到期表现为可读 fd，适合加入 epoll；读取对应的 uint64_t 到期计数，并处理非阻塞 EAGAIN、EINTR 等。多个到期可能合并，不是每次读取都恰好一次。"],"answerMarkdown":"timerfd 将定时到期表现为可读 fd，适合加入 epoll；读取对应的 uint64_t 到期计数，并处理非阻塞 EAGAIN、EINTR 等。多个到期可能合并，不是每次读取都恰好一次。\n\n**易错点：**到期计数不是连接 ID。\n\n**下一轮强化：**时间轮精度与懒取消清理","pitfalls":["到期计数不是连接 ID。"],"follow":"时间轮精度与懒取消清理","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":4,"sourceQuestion":1,"sourceRoundTitle":"timerfd 与大规模超时管理"},{"id":"daily-2026-10-12-r04-q02","module":"Linux","type":"概念题","title":"十万连接是否应每条连接建一个 timerfd？","prompt":"十万连接是否应每条连接建一个 timerfd？","promptMarkdown":"十万连接是否应每条连接建一个 timerfd？","answer":["通常采用一个或少量 timerfd 驱动最小堆或时间轮，统一管理连接期限，避免海量 fd 和调度成本。需测量精度、到期批量与更新成本。"],"answerMarkdown":"通常采用一个或少量 timerfd 驱动最小堆或时间轮，统一管理连接期限，避免海量 fd 和调度成本。需测量精度、到期批量与更新成本。\n\n**易错点：**精度需求决定堆或时间轮取舍。\n\n**下一轮强化：**时间轮精度与懒取消清理","pitfalls":["精度需求决定堆或时间轮取舍。"],"follow":"时间轮精度与懒取消清理","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":4,"sourceQuestion":2,"sourceRoundTitle":"timerfd 与大规模超时管理"},{"id":"daily-2026-10-12-r04-q03","module":"Linux","type":"场景题","title":"修改心跳 deadline 后旧超时任务仍关闭新会话，怎样修复？","prompt":"修改心跳 deadline 后旧超时任务仍关闭新会话，怎样修复？","promptMarkdown":"修改心跳 deadline 后旧超时任务仍关闭新会话，怎样修复？","answer":["记录任务 deadline、连接 ID 与 generation；到期后由 Reactor 比较当前代际和当前 deadline，过滤旧项。堆里的过期条目需有清理或压缩策略。"],"answerMarkdown":"记录任务 deadline、连接 ID 与 generation；到期后由 Reactor 比较当前代际和当前 deadline，过滤旧项。堆里的过期条目需有清理或压缩策略。\n\n**易错点：**generation 之外还要校验被更新的 deadline。\n\n**下一轮强化：**时间轮精度与懒取消清理","pitfalls":["generation 之外还要校验被更新的 deadline。"],"follow":"时间轮精度与懒取消清理","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":4,"sourceQuestion":3,"sourceRoundTitle":"timerfd 与大规模超时管理"},{"id":"daily-2026-10-12-r04-q04","module":"Linux","type":"代码题","title":"实现含 generation 的最小堆定时任务，按 now 取出到期项。","prompt":"实现含 generation 的最小堆定时任务，按 now 取出到期项。","promptMarkdown":"实现含 generation 的最小堆定时任务，按 now 取出到期项。","answer":["见代码，仅排序和输出，到期消费者仍要核对连接最新状态，不把堆弹出当成可以无条件关闭。"],"answerMarkdown":"见代码，仅排序和输出，到期消费者仍要核对连接最新状态，不把堆弹出当成可以无条件关闭。\n\n**易错点：**大批到期需要公平预算。\n\n```cpp\n#include <cassert>\n#include <cstdint>\n#include <queue>\n#include <vector>\nstruct Timer{long long deadline;int fd;std::uint64_t generation;};\nstruct Later{bool operator()(const Timer& a,const Timer& b)const{return a.deadline>b.deadline;}};\nclass Timers{\n    std::priority_queue<Timer,std::vector<Timer>,Later> heap_;\npublic:\n    void add(Timer t){heap_.push(t);}\n    std::vector<Timer> due(long long now){std::vector<Timer> out;while(!heap_.empty()&&heap_.top().deadline<=now){out.push_back(heap_.top());heap_.pop();}return out;}\n};\nint main(){Timers q;q.add({20,5,2});q.add({10,5,1});assert(q.due(9).empty());auto v=q.due(10);assert(v.size()==1&&v[0].generation==1);assert(q.due(20)[0].generation==2);}\n\n```\n\n**复杂度与边界：**插入 O(log N)，弹出 K 项 O(K log N)，存储 O(N)。未调用 timerfd/epoll，也未实现连接校验或取消堆条目。\n\n**下一轮强化：**时间轮精度与懒取消清理\n\n代码通过 C++17 严格警告编译及所附断言。","pitfalls":["大批到期需要公平预算。"],"follow":"时间轮精度与懒取消清理","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":4,"sourceQuestion":4,"sourceRoundTitle":"timerfd 与大规模超时管理"},{"id":"daily-2026-10-12-r04-q05","module":"项目追问","type":"场景题","title":"IM 心跳、业务 deadline 与路由 TTL 为什么不能混为一个定时器？","prompt":"IM 心跳、业务 deadline 与路由 TTL 为什么不能混为一个定时器？","promptMarkdown":"IM 心跳、业务 deadline 与路由 TTL 为什么不能混为一个定时器？","answer":["心跳判断连接活性，业务 deadline 限制请求预算，TTL 控制外部租约；时钟与权威不同。应明确各自错误处理和恢复，心跳超时也不直接证明持久消息丢失。"],"answerMarkdown":"心跳判断连接活性，业务 deadline 限制请求预算，TTL 控制外部租约；时钟与权威不同。应明确各自错误处理和恢复，心跳超时也不直接证明持久消息丢失。\n\n**易错点：**TTL 不是业务处理完成证明。\n\n**下一轮强化：**时间轮精度与懒取消清理","pitfalls":["TTL 不是业务处理完成证明。"],"follow":"时间轮精度与懒取消清理","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":4,"sourceQuestion":5,"sourceRoundTitle":"timerfd 与大规模超时管理"},{"id":"daily-2026-10-12-r05-q01","module":"TCP/HTTP","type":"概念题","title":"send 返回正数为什么仍不代表整条消息发完？","prompt":"send 返回正数为什么仍不代表整条消息发完？","promptMarkdown":"send 返回正数为什么仍不代表整条消息发完？","answer":["正数只表示本次交给内核的字节，可能少于要求，TCP 不保留消息边界；发送缓冲成功也不代表对端应用 ACK。"],"answerMarkdown":"正数只表示本次交给内核的字节，可能少于要求，TCP 不保留消息边界；发送缓冲成功也不代表对端应用 ACK。\n\n**易错点：**返回字节数不是消息数。\n\n**下一轮强化：**每连接背压与节点总预算","pitfalls":["返回字节数不是消息数。"],"follow":"每连接背压与节点总预算","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":5,"sourceQuestion":1,"sourceRoundTitle":"部分写、发送队列与慢客户端"},{"id":"daily-2026-10-12-r05-q02","module":"TCP/HTTP","type":"概念题","title":"可写事件应何时启用或关闭，EAGAIN 时要保存什么？","prompt":"可写事件应何时启用或关闭，EAGAIN 时要保存什么？","promptMarkdown":"可写事件应何时启用或关闭，EAGAIN 时要保存什么？","answer":["有待发送数据且暂时无法写时等待可写，队列清空后按事件模型关闭不必要订阅，防忙循环；保存对象所有权和偏移，EINTR 通常重试，EAGAIN 等待再续写。"],"answerMarkdown":"有待发送数据且暂时无法写时等待可写，队列清空后按事件模型关闭不必要订阅，防忙循环；保存对象所有权和偏移，EINTR 通常重试，EAGAIN 等待再续写。\n\n**易错点：**空队列持续关注可写可能忙循环。\n\n**下一轮强化：**每连接背压与节点总预算","pitfalls":["空队列持续关注可写可能忙循环。"],"follow":"每连接背压与节点总预算","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":5,"sourceQuestion":2,"sourceRoundTitle":"部分写、发送队列与慢客户端"},{"id":"daily-2026-10-12-r05-q03","module":"TCP/HTTP","type":"场景题","title":"慢客户端造成节点内存持续上涨，如何止损和根治？","prompt":"慢客户端造成节点内存持续上涨，如何止损和根治？","promptMarkdown":"慢客户端造成节点内存持续上涨，如何止损和根治？","answer":["关联每连接发送字节、年龄、ACK、网络和队列；限字节高水位，暂停生产或断开长期慢消费者，持久消息由补拉恢复，不能无限扩容。"],"answerMarkdown":"关联每连接发送字节、年龄、ACK、网络和队列；限字节高水位，暂停生产或断开长期慢消费者，持久消息由补拉恢复，不能无限扩容。\n\n**易错点：**只限条数不能控制字节。\n\n**下一轮强化：**每连接背压与节点总预算","pitfalls":["只限条数不能控制字节。"],"follow":"每连接背压与节点总预算","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":5,"sourceQuestion":3,"sourceRoundTitle":"部分写、发送队列与慢客户端"},{"id":"daily-2026-10-12-r05-q04","module":"TCP/HTTP","type":"代码题","title":"实现发送偏移模型：按完成字节前移，拒绝超过剩余范围的计数。","prompt":"实现发送偏移模型：按完成字节前移，拒绝超过剩余范围的计数。","promptMarkdown":"实现发送偏移模型：按完成字节前移，拒绝超过剩余范围的计数。","answer":["见代码，advance(0) 不前进但合法；实际 send 的错误与 EOF 需另外分类，不把所有返回值直接转换成 size_t。"],"answerMarkdown":"见代码，advance(0) 不前进但合法；实际 send 的错误与 EOF 需另外分类，不把所有返回值直接转换成 size_t。\n\n**易错点：**负错误值转无符号会变巨大。\n\n```cpp\n#include <cassert>\n#include <cstddef>\n#include <string>\n#include <string_view>\n#include <utility>\nclass Pending{\n    std::string bytes_;std::size_t offset_=0;\npublic:\n    explicit Pending(std::string s):bytes_(std::move(s)){}\n    std::string_view remaining()const{return std::string_view(bytes_).substr(offset_);}\n    bool advance(std::size_t n){if(n>bytes_.size()-offset_)return false;offset_+=n;return true;}\n};\nint main(){Pending p(\"hello\");assert(p.advance(2));assert(p.remaining()==\"llo\");assert(!p.advance(4));assert(p.advance(3));assert(p.remaining().empty());}\n\n```\n\n**复杂度与边界：**偏移操作 O(1)，拥有字符串空间 O(L)。视图寿命依赖 Pending，本例不实现网络与队列线程安全。\n\n**下一轮强化：**每连接背压与节点总预算\n\n代码通过 C++17 严格警告编译及所附断言。","pitfalls":["负错误值转无符号会变巨大。"],"follow":"每连接背压与节点总预算","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":5,"sourceQuestion":4,"sourceRoundTitle":"部分写、发送队列与慢客户端"},{"id":"daily-2026-10-12-r05-q05","module":"项目追问","type":"场景题","title":"可靠消息与发送队列被丢弃时如何协作恢复？","prompt":"可靠消息与发送队列被丢弃时如何协作恢复？","promptMarkdown":"可靠消息与发送队列被丢弃时如何协作恢复？","answer":["建议消息先有持久事实与稳定 ID，socket 队列只是传输尝试。重连按 ACK 水位补拉并去重；断开不能宣称已送达，也不应删除未确认持久数据。"],"answerMarkdown":"建议消息先有持久事实与稳定 ID，socket 队列只是传输尝试。重连按 ACK 水位补拉并去重；断开不能宣称已送达，也不应删除未确认持久数据。\n\n**易错点：**内核接收不等于客户端处理。\n\n**下一轮强化：**每连接背压与节点总预算","pitfalls":["内核接收不等于客户端处理。"],"follow":"每连接背压与节点总预算","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":5,"sourceQuestion":5,"sourceRoundTitle":"部分写、发送队列与慢客户端"},{"id":"daily-2026-10-12-r06-q01","module":"Nginx","type":"概念题","title":"proxy_read_timeout 限制整条连接总寿命吗？","prompt":"proxy_read_timeout 限制整条连接总寿命吗？","promptMarkdown":"proxy_read_timeout 限制整条连接总寿命吗？","answer":["它约束读取上游数据的相邻操作间隔，不是整个响应或 WebSocket 的固定总寿命。实际值需查生效配置、继承与日志。"],"answerMarkdown":"它约束读取上游数据的相邻操作间隔，不是整个响应或 WebSocket 的固定总寿命。实际值需查生效配置、继承与日志。\n\n**易错点：**相邻读取超时不是连接最大年龄。\n\n**下一轮强化：**代理多层超时与客户端后台限制","pitfalls":["相邻读取超时不是连接最大年龄。"],"follow":"代理多层超时与客户端后台限制","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":6,"sourceQuestion":1,"sourceRoundTitle":"WebSocket 空闲超时与心跳方向"},{"id":"daily-2026-10-12-r06-q02","module":"Nginx","type":"概念题","title":"客户端定时发数据是否一定能重置代理对上游的读超时？","prompt":"客户端定时发数据是否一定能重置代理对上游的读超时？","promptMarkdown":"客户端定时发数据是否一定能重置代理对上游的读超时？","answer":["不一定。客户端发给上游与代理读取上游响应是两个方向，需上游产生可被代理读取的数据；心跳实现应明确谁发、谁回复与每段空闲限制。"],"answerMarkdown":"不一定。客户端发给上游与代理读取上游响应是两个方向，需上游产生可被代理读取的数据；心跳实现应明确谁发、谁回复与每段空闲限制。\n\n**易错点：**流量方向不能混淆。\n\n**下一轮强化：**代理多层超时与客户端后台限制","pitfalls":["流量方向不能混淆。"],"follow":"代理多层超时与客户端后台限制","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":6,"sourceQuestion":2,"sourceRoundTitle":"WebSocket 空闲超时与心跳方向"},{"id":"daily-2026-10-12-r06-q03","module":"Nginx","type":"场景题","title":"升级成功后空闲约一分钟断开，应查哪些证据？","prompt":"升级成功后空闲约一分钟断开，应查哪些证据？","promptMarkdown":"升级成功后空闲约一分钟断开，应查哪些证据？","answer":["核对 Upgrade/Connection 配置、生效 read timeout、负载均衡层和客户端后台策略；关联代理日志、节点关闭原因与 Ping/Pong 时间，不先一律增加超时。"],"answerMarkdown":"核对 Upgrade/Connection 配置、生效 read timeout、负载均衡层和客户端后台策略；关联代理日志、节点关闭原因与 Ping/Pong 时间，不先一律增加超时。\n\n**易错点：**一分钟现象也可能来自其他链路。\n\n**下一轮强化：**代理多层超时与客户端后台限制","pitfalls":["一分钟现象也可能来自其他链路。"],"follow":"代理多层超时与客户端后台限制","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":6,"sourceQuestion":3,"sourceRoundTitle":"WebSocket 空闲超时与心跳方向"},{"id":"daily-2026-10-12-r06-q04","module":"Nginx","type":"代码题","title":"实现上游活动超时模型：只以上游向代理的数据推进读活动时间。","prompt":"实现上游活动超时模型：只以上游向代理的数据推进读活动时间。","promptMarkdown":"实现上游活动超时模型：只以上游向代理的数据推进读活动时间。","answer":["见代码。now 必须单调且不回退，实际比较要由同一时钟域提供；模型无 Nginx。"],"answerMarkdown":"见代码。now 必须单调且不回退，实际比较要由同一时钟域提供；模型无 Nginx。\n\n**易错点：**时钟回退不能当合法活动。\n\n```cpp\n#include <cassert>\n#include <stdexcept>\nclass Idle{\n    long long last_=0,limit_;\npublic:\n    explicit Idle(long long limit):limit_(limit){if(limit<=0)throw std::invalid_argument(\"limit\");}\n    bool upstream(long long now){if(now<last_)return false;last_=now;return true;}\n    bool expired(long long now)const{if(now<last_)return false;return now-last_>=limit_;}\n};\nint main(){Idle s(60);assert(!s.expired(59));assert(s.expired(60));assert(s.upstream(50));assert(!s.expired(60));assert(s.expired(110));assert(!s.upstream(49));}\n\n```\n\n**复杂度与边界：**O(1) 时间/空间。非负时间前提下安全；仅教学模型，没有真实连接、双向心跳或 deadline 总预算。\n\n**下一轮强化：**代理多层超时与客户端后台限制\n\n代码通过 C++17 严格警告编译及所附断言。","pitfalls":["时钟回退不能当合法活动。"],"follow":"代理多层超时与客户端后台限制","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":6,"sourceQuestion":4,"sourceRoundTitle":"WebSocket 空闲超时与心跳方向"},{"id":"daily-2026-10-12-r06-q05","module":"项目追问","type":"场景题","title":"IM 如何设计 Ping/Pong、超时和重连退避？","prompt":"IM 如何设计 Ping/Pong、超时和重连退避？","promptMarkdown":"IM 如何设计 Ping/Pong、超时和重连退避？","answer":["建议心跳间隔低于路径空闲阈值并留裕量，超时须结合事件循环拥塞与客户端后台行为；重连指数退避加抖动，重新鉴权、恢复订阅与 ACK 补拉，避免重连风暴。"],"answerMarkdown":"建议心跳间隔低于路径空闲阈值并留裕量，超时须结合事件循环拥塞与客户端后台行为；重连指数退避加抖动，重新鉴权、恢复订阅与 ACK 补拉，避免重连风暴。\n\n**易错点：**心跳不能代替消息 ACK。\n\n**下一轮强化：**代理多层超时与客户端后台限制","pitfalls":["心跳不能代替消息 ACK。"],"follow":"代理多层超时与客户端后台限制","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":6,"sourceQuestion":5,"sourceRoundTitle":"WebSocket 空闲超时与心跳方向"},{"id":"daily-2026-10-12-r07-q01","module":"MySQL","type":"概念题","title":"撤回为什么不能只检查请求里的 sender_id？","prompt":"撤回为什么不能只检查请求里的 sender_id？","promptMarkdown":"撤回为什么不能只检查请求里的 sender_id？","answer":["身份来自可信认证上下文，而非客户端自报；还要核对消息归属和访问范围。未授权者不能因为知道 message_id 就撤回。"],"answerMarkdown":"身份来自可信认证上下文，而非客户端自报；还要核对消息归属和访问范围。未授权者不能因为知道 message_id 就撤回。\n\n**易错点：**请求字段不是认证身份。\n\n**下一轮强化：**条件 UPDATE、Outbox 与客户端版本","pitfalls":["请求字段不是认证身份。"],"follow":"条件 UPDATE、Outbox 与客户端版本","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":7,"sourceQuestion":1,"sourceRoundTitle":"消息撤回的权限与原子条件"},{"id":"daily-2026-10-12-r07-q02","module":"MySQL","type":"概念题","title":"撤回窗口检查与状态更新为何应共同原子执行？","prompt":"撤回窗口检查与状态更新为何应共同原子执行？","promptMarkdown":"撤回窗口检查与状态更新为何应共同原子执行？","answer":["先查再改有竞态；建议条件 UPDATE 或适当锁定事务，包含发送者、状态与规定时间，检查受影响行数，并明确窗口由数据库权威时间判断。"],"answerMarkdown":"先查再改有竞态；建议条件 UPDATE 或适当锁定事务，包含发送者、状态与规定时间，检查受影响行数，并明确窗口由数据库权威时间判断。\n\n**易错点：**应用节点时间可能不同。\n\n**下一轮强化：**条件 UPDATE、Outbox 与客户端版本","pitfalls":["应用节点时间可能不同。"],"follow":"条件 UPDATE、Outbox 与客户端版本","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":7,"sourceQuestion":2,"sourceRoundTitle":"消息撤回的权限与原子条件"},{"id":"daily-2026-10-12-r07-q03","module":"MySQL","type":"场景题","title":"两个节点同时撤回，一边通知成功一边更新零行，怎样处理？","prompt":"两个节点同时撤回，一边通知成功一边更新零行，怎样处理？","promptMarkdown":"两个节点同时撤回，一边通知成功一边更新零行，怎样处理？","answer":["关联 request ID、消息版本与事务结果；区分已撤回重复、未授权、超窗和不存在。事件应与实际状态同事务，不能更新失败却直接发布成功通知。"],"answerMarkdown":"关联 request ID、消息版本与事务结果；区分已撤回重复、未授权、超窗和不存在。事件应与实际状态同事务，不能更新失败却直接发布成功通知。\n\n**易错点：**零行不是固定一种错误。\n\n**下一轮强化：**条件 UPDATE、Outbox 与客户端版本","pitfalls":["零行不是固定一种错误。"],"follow":"条件 UPDATE、Outbox 与客户端版本","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":7,"sourceQuestion":3,"sourceRoundTitle":"消息撤回的权限与原子条件"},{"id":"daily-2026-10-12-r07-q04","module":"MySQL","type":"代码题","title":"实现受锁保护的消息撤回模型：真实操作者、截止时间、已撤回幂等。","prompt":"实现受锁保护的消息撤回模型：真实操作者、截止时间、已撤回幂等。","promptMarkdown":"实现受锁保护的消息撤回模型：真实操作者、截止时间、已撤回幂等。","answer":["见代码，模拟明确结果枚举。已授权发送者对已撤回消息重复操作返回 Already，超窗对未撤回消息拒绝；生产规则应明确。"],"answerMarkdown":"见代码，模拟明确结果枚举。已授权发送者对已撤回消息重复操作返回 Already，超窗对未撤回消息拒绝；生产规则应明确。\n\n**易错点：**幂等重试的超窗语义要约定。\n\n```cpp\n#include <cassert>\n#include <mutex>\nenum class Result{Done,Already,Forbidden,Expired};\nclass Message{\n    std::mutex m_;int sender_;long long deadline_;bool recalled_=false;\npublic:\n    Message(int sender,long long deadline):sender_(sender),deadline_(deadline){}\n    Result recall(int actor,long long now){\n        std::lock_guard<std::mutex> lock(m_);\n        if(actor!=sender_)return Result::Forbidden;\n        if(recalled_)return Result::Already;\n        if(now<0||now>deadline_)return Result::Expired;\n        recalled_=true;return Result::Done;\n    }\n};\nint main(){Message m(7,100);assert(m.recall(8,10)==Result::Forbidden);assert(m.recall(7,100)==Result::Done);assert(m.recall(7,101)==Result::Already);Message old(7,10);assert(old.recall(7,11)==Result::Expired);}\n\n```\n\n**复杂度与边界：**O(1) 状态操作，锁等待另计；没有 SQL、持久化或权威时钟。\n\n**下一轮强化：**条件 UPDATE、Outbox 与客户端版本\n\n代码通过 C++17 严格警告编译及所附断言。","pitfalls":["幂等重试的超窗语义要约定。"],"follow":"条件 UPDATE、Outbox 与客户端版本","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":7,"sourceQuestion":4,"sourceRoundTitle":"消息撤回的权限与原子条件"},{"id":"daily-2026-10-12-r07-q05","module":"项目追问","type":"场景题","title":"IM 撤回事件、历史消息与离线补拉怎样保证一致？","prompt":"IM 撤回事件、历史消息与离线补拉怎样保证一致？","promptMarkdown":"IM 撤回事件、历史消息与离线补拉怎样保证一致？","answer":["建议 MySQL 保存撤回状态或墓碑与版本，同事务写 Outbox；客户端按版本收敛，历史与补拉显示撤回占位，不能只发送一条临时 Pub/Sub 而保留旧正文展示。"],"answerMarkdown":"建议 MySQL 保存撤回状态或墓碑与版本，同事务写 Outbox；客户端按版本收敛，历史与补拉显示撤回占位，不能只发送一条临时 Pub/Sub 而保留旧正文展示。\n\n**易错点：**缓存与多设备仍需失效恢复。\n\n**下一轮强化：**条件 UPDATE、Outbox 与客户端版本","pitfalls":["缓存与多设备仍需失效恢复。"],"follow":"条件 UPDATE、Outbox 与客户端版本","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":7,"sourceQuestion":5,"sourceRoundTitle":"消息撤回的权限与原子条件"},{"id":"daily-2026-10-12-r08-q01","module":"MySQL","type":"概念题","title":"RR 快照为何不能保证所有业务查询都看到同一版本？","prompt":"RR 快照为何不能保证所有业务查询都看到同一版本？","promptMarkdown":"RR 快照为何不能保证所有业务查询都看到同一版本？","answer":["RR 的普通一致性读快照通常复用，但自身写入与当前读有不同语义；不能把事务里所有读取都归为同一历史快照，DDL 等还有额外边界。"],"answerMarkdown":"RR 的普通一致性读快照通常复用，但自身写入与当前读有不同语义；不能把事务里所有读取都归为同一历史快照，DDL 等还有额外边界。\n\n**易错点：**RR 不等于所有读取都固定历史状态。\n\n**下一轮强化：**快照观察与当前条件提交","pitfalls":["RR 不等于所有读取都固定历史状态。"],"follow":"快照观察与当前条件提交","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":8,"sourceQuestion":1,"sourceRoundTitle":"读已提交、可重复读与混合读"},{"id":"daily-2026-10-12-r08-q02","module":"MySQL","type":"概念题","title":"锁定读与普通 SELECT 混用时有哪些边界？","prompt":"锁定读与普通 SELECT 混用时有哪些边界？","promptMarkdown":"锁定读与普通 SELECT 混用时有哪些边界？","answer":["锁定读读取需要锁定的当前状态，可能等待并发事务；普通快照检查只是先前观察。实际修改应重新检查业务条件，不能继续信任旧快照。"],"answerMarkdown":"锁定读读取需要锁定的当前状态，可能等待并发事务；普通快照检查只是先前观察。实际修改应重新检查业务条件，不能继续信任旧快照。\n\n**易错点：**FOR UPDATE 不是普通快照读加一把锁。\n\n**下一轮强化：**快照观察与当前条件提交","pitfalls":["FOR UPDATE 不是普通快照读加一把锁。"],"follow":"快照观察与当前条件提交","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":8,"sourceQuestion":2,"sourceRoundTitle":"读已提交、可重复读与混合读"},{"id":"daily-2026-10-12-r08-q03","module":"MySQL","type":"场景题","title":"先普通 SELECT 判断消息存在，再 FOR UPDATE 修改，状态已变化应怎么办？","prompt":"先普通 SELECT 判断消息存在，再 FOR UPDATE 修改，状态已变化应怎么办？","promptMarkdown":"先普通 SELECT 判断消息存在，再 FOR UPDATE 修改，状态已变化应怎么办？","answer":["锁内重新验证归属、状态、版本和窗口，条件不满足时返回明确冲突；别把旧判断作为必然成功依据，缩短事务并用正确索引。"],"answerMarkdown":"锁内重新验证归属、状态、版本和窗口，条件不满足时返回明确冲突；别把旧判断作为必然成功依据，缩短事务并用正确索引。\n\n**易错点：**前置检查可能已陈旧。\n\n**下一轮强化：**快照观察与当前条件提交","pitfalls":["前置检查可能已陈旧。"],"follow":"快照观察与当前条件提交","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":8,"sourceQuestion":3,"sourceRoundTitle":"读已提交、可重复读与混合读"},{"id":"daily-2026-10-12-r08-q04","module":"MySQL","type":"代码题","title":"实现版本条件更新模型，旧版本更新被拒绝并返回新版本。","prompt":"实现版本条件更新模型，旧版本更新被拒绝并返回新版本。","promptMarkdown":"实现版本条件更新模型，旧版本更新被拒绝并返回新版本。","answer":["见代码，版本到上限拒绝，不回绕；模型单线程，不等于数据库并发控制。"],"answerMarkdown":"见代码，版本到上限拒绝，不回绕；模型单线程，不等于数据库并发控制。\n\n**易错点：**版本溢出不可默默回绕。\n\n```cpp\n#include <cassert>\n#include <cstdint>\n#include <limits>\nclass Versioned{\n    std::uint64_t version_=1;int value_=0;\npublic:\n    bool update(std::uint64_t expected,int value){\n        if(expected!=version_||version_==std::numeric_limits<std::uint64_t>::max())return false;\n        value_=value;++version_;return true;\n    }\n    std::uint64_t version()const{return version_;}\n    int value()const{return value_;}\n};\nint main(){Versioned v;assert(v.update(1,7));assert(!v.update(1,8));assert(v.value()==7&&v.version()==2);assert(v.update(2,9));}\n\n```\n\n**复杂度与边界：**O(1) 时间/空间，单线程模型。真实 SQL 应原子比较更新并检查受影响行数。\n\n**下一轮强化：**快照观察与当前条件提交\n\n代码通过 C++17 严格警告编译及所附断言。","pitfalls":["版本溢出不可默默回绕。"],"follow":"快照观察与当前条件提交","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":8,"sourceQuestion":4,"sourceRoundTitle":"读已提交、可重复读与混合读"},{"id":"daily-2026-10-12-r08-q05","module":"项目追问","type":"场景题","title":"IM 消息编辑或撤回如何处理版本冲突与重试？","prompt":"IM 消息编辑或撤回如何处理版本冲突与重试？","promptMarkdown":"IM 消息编辑或撤回如何处理版本冲突与重试？","answer":["建议条件更新加稳定幂等键，版本冲突重新读取后让业务决定，不盲目覆盖；已提交的事件携带新版本，客户端忽略旧版本迟到事件。"],"answerMarkdown":"建议条件更新加稳定幂等键，版本冲突重新读取后让业务决定，不盲目覆盖；已提交的事件携带新版本，客户端忽略旧版本迟到事件。\n\n**易错点：**重试不能更换请求业务含义。\n\n**下一轮强化：**快照观察与当前条件提交","pitfalls":["重试不能更换请求业务含义。"],"follow":"快照观察与当前条件提交","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":8,"sourceQuestion":5,"sourceRoundTitle":"读已提交、可重复读与混合读"},{"id":"daily-2026-10-12-r09-q01","module":"Redis","type":"概念题","title":"Redis 中撤销 Token 后，已建立 WebSocket 会自动失效吗？","prompt":"Redis 中撤销 Token 后，已建立 WebSocket 会自动失效吗？","promptMarkdown":"Redis 中撤销 Token 后，已建立 WebSocket 会自动失效吗？","answer":["不会自动失效；连接已通过的鉴权状态要由应用主动失效、逐命令验证或按版本重新核验。Redis 删除键不自动调用所有节点的 close。"],"answerMarkdown":"不会自动失效；连接已通过的鉴权状态要由应用主动失效、逐命令验证或按版本重新核验。Redis 删除键不自动调用所有节点的 close。\n\n**易错点：**连接鉴权不是持续授权。\n\n**下一轮强化：**认证版本持久性与多节点故障","pitfalls":["连接鉴权不是持续授权。"],"follow":"认证版本持久性与多节点故障","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":9,"sourceQuestion":1,"sourceRoundTitle":"Token 撤销与既有长连接"},{"id":"daily-2026-10-12-r09-q02","module":"Redis","type":"概念题","title":"撤销生效时间为什么需要明确多节点约束？","prompt":"撤销生效时间为什么需要明确多节点约束？","promptMarkdown":"撤销生效时间为什么需要明确多节点约束？","answer":["通知传播、本地缓存、在途命令与故障切换都影响生效。需要定义从权威提交到哪些操作被拒绝的界限，及不可用时的拒绝或受限策略。"],"answerMarkdown":"通知传播、本地缓存、在途命令与故障切换都影响生效。需要定义从权威提交到哪些操作被拒绝的界限，及不可用时的拒绝或受限策略。\n\n**易错点：**生效时间是协议，不是口头立即。\n\n**下一轮强化：**认证版本持久性与多节点故障","pitfalls":["生效时间是协议，不是口头立即。"],"follow":"认证版本持久性与多节点故障","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":9,"sourceQuestion":2,"sourceRoundTitle":"Token 撤销与既有长连接"},{"id":"daily-2026-10-12-r09-q03","module":"Redis","type":"场景题","title":"撤销通知丢失，一节点继续接受旧连接命令，如何恢复？","prompt":"撤销通知丢失，一节点继续接受旧连接命令，如何恢复？","promptMarkdown":"撤销通知丢失，一节点继续接受旧连接命令，如何恢复？","answer":["记录撤销版本、节点已见版本、最后校验与消息执行；通知仅作加速，补以有界复查或权威校验，恢复后拒绝旧版本，并清理连接与缓存。"],"answerMarkdown":"记录撤销版本、节点已见版本、最后校验与消息执行；通知仅作加速，补以有界复查或权威校验，恢复后拒绝旧版本，并清理连接与缓存。\n\n**易错点：**Pub/Sub 不补断线通知。\n\n**下一轮强化：**认证版本持久性与多节点故障","pitfalls":["Pub/Sub 不补断线通知。"],"follow":"认证版本持久性与多节点故障","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":9,"sourceQuestion":3,"sourceRoundTitle":"Token 撤销与既有长连接"},{"id":"daily-2026-10-12-r09-q04","module":"Redis","type":"代码题","title":"实现认证版本判断：旧连接版本小于当前权威版本时拒绝业务命令。","prompt":"实现认证版本判断：旧连接版本小于当前权威版本时拒绝业务命令。","promptMarkdown":"实现认证版本判断：旧连接版本小于当前权威版本时拒绝业务命令。","answer":["见代码，要求严格相等，连接版本超前也不接受；不可访问权威状态时拒绝。输入必须来自可信权威事实。"],"answerMarkdown":"见代码，要求严格相等，连接版本超前也不接受；不可访问权威状态时拒绝。输入必须来自可信权威事实。\n\n**易错点：**相同版本仍需有效 Token 和权限。\n\n```cpp\n#include <cassert>\n#include <cstdint>\n#include <optional>\nbool authorized(std::uint64_t session,std::optional<std::uint64_t> authority,bool tokenValid){\n    return tokenValid && authority && session==*authority;\n}\nint main(){assert(authorized(2,2,true));assert(!authorized(1,2,true));assert(!authorized(3,2,true));assert(!authorized(2,std::nullopt,true));assert(!authorized(2,2,false));}\n\n```\n\n**复杂度与边界：**O(1) 时间/空间，只演示保守授权判断，不实现 Token 验签、缓存或网络撤销协议。\n\n**下一轮强化：**认证版本持久性与多节点故障\n\n代码通过 C++17 严格警告编译及所附断言。","pitfalls":["相同版本仍需有效 Token 和权限。"],"follow":"认证版本持久性与多节点故障","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":9,"sourceQuestion":4,"sourceRoundTitle":"Token 撤销与既有长连接"},{"id":"daily-2026-10-12-r09-q05","module":"项目追问","type":"场景题","title":"你的 IM 如何区分立即撤销、有限延迟生效和依赖故障策略？","prompt":"你的 IM 如何区分立即撤销、有限延迟生效和依赖故障策略？","promptMarkdown":"你的 IM 如何区分立即撤销、有限延迟生效和依赖故障策略？","answer":["建议按需求选择每命令强校验、短期版本缓存或受限会话；严格撤销不能仅靠异步 Pub/Sub 与 Redis 异步复制。已开始事务怎样处理也要定义，不能把关闭 socket 当成撤销全部副作用。"],"answerMarkdown":"建议按需求选择每命令强校验、短期版本缓存或受限会话；严格撤销不能仅靠异步 Pub/Sub 与 Redis 异步复制。已开始事务怎样处理也要定义，不能把关闭 socket 当成撤销全部副作用。\n\n**易错点：**TTL 不能代替立即撤销。\n\n**下一轮强化：**认证版本持久性与多节点故障","pitfalls":["TTL 不能代替立即撤销。"],"follow":"认证版本持久性与多节点故障","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":9,"sourceQuestion":5,"sourceRoundTitle":"Token 撤销与既有长连接"},{"id":"daily-2026-10-12-r10-q01","module":"Redis","type":"概念题","title":"XREADGROUP、PEL 和 XACK 分别承担什么职责？","prompt":"XREADGROUP、PEL 和 XACK 分别承担什么职责？","promptMarkdown":"XREADGROUP、PEL 和 XACK 分别承担什么职责？","answer":["消费组读取分配消息，PEL 跟踪尚未确认的待处理消息，XACK 移除对应待确认记录；它不是数据库业务事务，也不自动删除 Stream 条目。"],"answerMarkdown":"消费组读取分配消息，PEL 跟踪尚未确认的待处理消息，XACK 移除对应待确认记录；它不是数据库业务事务，也不自动删除 Stream 条目。\n\n**易错点：**ACK 不是消息正文删除。\n\n**下一轮强化：**PEL 接管、死信与裁剪","pitfalls":["ACK 不是消息正文删除。"],"follow":"PEL 接管、死信与裁剪","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":10,"sourceQuestion":1,"sourceRoundTitle":"Redis Streams 消费确认与幂等"},{"id":"daily-2026-10-12-r10-q02","module":"Redis","type":"概念题","title":"XACK 能否证明业务副作用绝对只执行一次？","prompt":"XACK 能否证明业务副作用绝对只执行一次？","promptMarkdown":"XACK 能否证明业务副作用绝对只执行一次？","answer":["不能。业务提交与 ACK 之间有窗口，重投可能重复执行；需业务侧持久去重、事务与状态约束。过早 ACK 也会丢失未完成处理。"],"answerMarkdown":"不能。业务提交与 ACK 之间有窗口，重投可能重复执行；需业务侧持久去重、事务与状态约束。过早 ACK 也会丢失未完成处理。\n\n**易错点：**投递确认不能代替业务幂等。\n\n**下一轮强化：**PEL 接管、死信与裁剪","pitfalls":["投递确认不能代替业务幂等。"],"follow":"PEL 接管、死信与裁剪","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":10,"sourceQuestion":2,"sourceRoundTitle":"Redis Streams 消费确认与幂等"},{"id":"daily-2026-10-12-r10-q03","module":"Redis","type":"场景题","title":"消费者业务已提交却在 XACK 前崩溃，重领后如何避免重复？","prompt":"消费者业务已提交却在 XACK 前崩溃，重领后如何避免重复？","promptMarkdown":"消费者业务已提交却在 XACK 前崩溃，重领后如何避免重复？","answer":["按 event_id 查持久处理事实，重复返回已处理，数据库副作用和去重记录同事务；之后再 ACK。接管、最大重试、死信与保留策略都需明确。"],"answerMarkdown":"按 event_id 查持久处理事实，重复返回已处理，数据库副作用和去重记录同事务；之后再 ACK。接管、最大重试、死信与保留策略都需明确。\n\n**易错点：**去重事实也要持久。\n\n**下一轮强化：**PEL 接管、死信与裁剪","pitfalls":["去重事实也要持久。"],"follow":"PEL 接管、死信与裁剪","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":10,"sourceQuestion":3,"sourceRoundTitle":"Redis Streams 消费确认与幂等"},{"id":"daily-2026-10-12-r10-q04","module":"Redis","type":"代码题","title":"实现事件幂等计数：重复 event_id 不累加，溢出时不记录新事件。","prompt":"实现事件幂等计数：重复 event_id 不累加，溢出时不记录新事件。","promptMarkdown":"实现事件幂等计数：重复 event_id 不累加，溢出时不记录新事件。","answer":["见代码。检查计数上限后插入 ID，插入成功才增加计数；模型仅在进程内生效。"],"answerMarkdown":"见代码。检查计数上限后插入 ID，插入成功才增加计数；模型仅在进程内生效。\n\n**易错点：**失败前不能记录为已处理。\n\n```cpp\n#include <cassert>\n#include <cstdint>\n#include <limits>\n#include <stdexcept>\n#include <string>\n#include <unordered_set>\nclass Events{\n    std::unordered_set<std::string> seen_;std::uint64_t count_=0;\npublic:\n    bool apply(const std::string& id){\n        if(seen_.count(id))return false;\n        if(count_==std::numeric_limits<std::uint64_t>::max())throw std::overflow_error(\"count\");\n        seen_.insert(id);++count_;return true;\n    }\n    std::uint64_t count()const{return count_;}\n};\nint main(){Events e;assert(e.apply(\"event1\"));assert(!e.apply(\"event1\"));assert(e.apply(\"event2\"));assert(e.count()==2);}\n\n```\n\n**复杂度与边界：**哈希期望 O(1)、最坏 O(N)，加字符串成本，空间随事件增长。无持久化、并发或 Redis ACK。\n\n**下一轮强化：**PEL 接管、死信与裁剪\n\n代码通过 C++17 严格警告编译及所附断言。","pitfalls":["失败前不能记录为已处理。"],"follow":"PEL 接管、死信与裁剪","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":10,"sourceQuestion":4,"sourceRoundTitle":"Redis Streams 消费确认与幂等"},{"id":"daily-2026-10-12-r10-q05","module":"项目追问","type":"场景题","title":"IM 用 Streams 替换 Pub/Sub 后，还需要哪些可靠性边界？","prompt":"IM 用 Streams 替换 Pub/Sub 后，还需要哪些可靠性边界？","promptMarkdown":"IM 用 Streams 替换 Pub/Sub 后，还需要哪些可靠性边界？","answer":["建议明确持久配置与故障转移、消费者接管、裁剪不删未完成任务、消费幂等和数据库边界；Streams 是工具，不自动保证多系统恰好一次。"],"answerMarkdown":"建议明确持久配置与故障转移、消费者接管、裁剪不删未完成任务、消费幂等和数据库边界；Streams 是工具，不自动保证多系统恰好一次。\n\n**易错点：**裁剪与恢复窗口必须一致。\n\n**下一轮强化：**PEL 接管、死信与裁剪","pitfalls":["裁剪与恢复窗口必须一致。"],"follow":"PEL 接管、死信与裁剪","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":10,"sourceQuestion":5,"sourceRoundTitle":"Redis Streams 消费确认与幂等"},{"id":"daily-2026-10-12-r11-q01","module":"TCP/HTTP","type":"概念题","title":"指数退避为什么还要加抖动和最大上限？","prompt":"指数退避为什么还要加抖动和最大上限？","promptMarkdown":"指数退避为什么还要加抖动和最大上限？","answer":["指数退避减少持续失败下的压力，抖动降低同步重试波峰，cap 限制等待；还要最大次数、总预算与错误分类，不能无限重试永久故障。"],"answerMarkdown":"指数退避减少持续失败下的压力，抖动降低同步重试波峰，cap 限制等待；还要最大次数、总预算与错误分类，不能无限重试永久故障。\n\n**易错点：**只有指数没有抖动仍会同步。\n\n**下一轮强化：**恢复优先级与重试风暴指标","pitfalls":["只有指数没有抖动仍会同步。"],"follow":"恢复优先级与重试风暴指标","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":11,"sourceQuestion":1,"sourceRoundTitle":"故障重连退避与统一预算"},{"id":"daily-2026-10-12-r11-q02","module":"TCP/HTTP","type":"概念题","title":"重试是否应该重新获得完整 deadline？","prompt":"重试是否应该重新获得完整 deadline？","promptMarkdown":"重试是否应该重新获得完整 deadline？","answer":["通常复用原始逻辑操作的总预算，排队、等待、发现与重试都占时间；每次重置会让总耗时无界。新的独立业务请求才有自己的预算。"],"answerMarkdown":"通常复用原始逻辑操作的总预算，排队、等待、发现与重试都占时间；每次重置会让总耗时无界。新的独立业务请求才有自己的预算。\n\n**易错点：**预算应覆盖整个逻辑请求。\n\n**下一轮强化：**恢复优先级与重试风暴指标","pitfalls":["预算应覆盖整个逻辑请求。"],"follow":"恢复优先级与重试风暴指标","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":11,"sourceQuestion":2,"sourceRoundTitle":"故障重连退避与统一预算"},{"id":"daily-2026-10-12-r11-q03","module":"TCP/HTTP","type":"场景题","title":"Sentinel 切换后所有客户端同时重连，如何避免恢复流量压垮服务？","prompt":"Sentinel 切换后所有客户端同时重连，如何避免恢复流量压垮服务？","promptMarkdown":"Sentinel 切换后所有客户端同时重连，如何避免恢复流量压垮服务？","answer":["限制节点与客户端并发重连，分散时间，优先认证与消息恢复容量，减少无效回源；Redis 主节点重新发现与角色验证，避免反复连接旧主。"],"answerMarkdown":"限制节点与客户端并发重连，分散时间，优先认证与消息恢复容量，减少无效回源；Redis 主节点重新发现与角色验证，避免反复连接旧主。\n\n**易错点：**故障恢复也需要限流。\n\n**下一轮强化：**恢复优先级与重试风暴指标","pitfalls":["故障恢复也需要限流。"],"follow":"恢复优先级与重试风暴指标","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":11,"sourceQuestion":3,"sourceRoundTitle":"故障重连退避与统一预算"},{"id":"daily-2026-10-12-r11-q04","module":"TCP/HTTP","type":"代码题","title":"实现饱和指数退避，不用移位导致溢出，达到 cap 后保持 cap。","prompt":"实现饱和指数退避，不用移位导致溢出，达到 cap 后保持 cap。","promptMarkdown":"实现饱和指数退避，不用移位导致溢出，达到 cap 后保持 cap。","answer":["见代码，倍增前比较 cap/2，超限饱和。这里只计算基础延迟，没有随机抖动或真实等待。"],"answerMarkdown":"见代码，倍增前比较 cap/2，超限饱和。这里只计算基础延迟，没有随机抖动或真实等待。\n\n**易错点：**移位与乘法都可能溢出。\n\n```cpp\n#include <cassert>\n#include <cstdint>\n#include <stdexcept>\nstd::uint64_t delay(std::uint64_t base,std::uint64_t cap,unsigned attempts){\n    if(!base||!cap||base>cap)throw std::invalid_argument(\"budget\");\n    auto value=base;\n    while(attempts-- && value<cap){if(value>cap/2)return cap;value*=2;}\n    return value;\n}\nint main(){assert(delay(10,100,0)==10);assert(delay(10,100,3)==80);assert(delay(10,100,4)==100);assert(delay(10,100,1000)==100);}\n\n```\n\n**复杂度与边界：**O(min(attempts,log(cap/base))) 时间，O(1) 空间。抖动、deadline 和取消由调用者另设计。\n\n**下一轮强化：**恢复优先级与重试风暴指标\n\n代码通过 C++17 严格警告编译及所附断言。","pitfalls":["移位与乘法都可能溢出。"],"follow":"恢复优先级与重试风暴指标","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":11,"sourceQuestion":4,"sourceRoundTitle":"故障重连退避与统一预算"},{"id":"daily-2026-10-12-r11-q05","module":"项目追问","type":"场景题","title":"IM 重连后哪些状态需要验证而不是直接信任旧缓存？","prompt":"IM 重连后哪些状态需要验证而不是直接信任旧缓存？","promptMarkdown":"IM 重连后哪些状态需要验证而不是直接信任旧缓存？","answer":["建议重新鉴权、核对版本与撤销、恢复订阅与路由 generation、按持久 ACK 补拉；旧在线状态可能过期或在故障中回退，不能直接复活。"],"answerMarkdown":"建议重新鉴权、核对版本与撤销、恢复订阅与路由 generation、按持久 ACK 补拉；旧在线状态可能过期或在故障中回退，不能直接复活。\n\n**易错点：**重连成功不等于消息恢复完成。\n\n**下一轮强化：**恢复优先级与重试风暴指标","pitfalls":["重连成功不等于消息恢复完成。"],"follow":"恢复优先级与重试风暴指标","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":11,"sourceQuestion":5,"sourceRoundTitle":"故障重连退避与统一预算"},{"id":"daily-2026-10-12-r12-q01","module":"项目追问","type":"概念题","title":"通知乱序时，旧正文事件能否覆盖已撤回状态？","prompt":"通知乱序时，旧正文事件能否覆盖已撤回状态？","promptMarkdown":"通知乱序时，旧正文事件能否覆盖已撤回状态？","answer":["不能无条件覆盖；客户端应按消息版本和合法状态规则收敛，历史补拉返回权威状态。网络到达时间不等于业务发生顺序，撤回也不能只存在内存通知。"],"answerMarkdown":"不能无条件覆盖；客户端应按消息版本和合法状态规则收敛，历史补拉返回权威状态。网络到达时间不等于业务发生顺序，撤回也不能只存在内存通知。\n\n**易错点：**迟到顺序不能覆盖业务版本。\n\n**下一轮强化：**故障注入报告与已实现能力陈述","pitfalls":["迟到顺序不能覆盖业务版本。"],"follow":"故障注入报告与已实现能力陈述","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":12,"sourceQuestion":1,"sourceRoundTitle":"消息撤回、编辑与迟到事件复盘"},{"id":"daily-2026-10-12-r12-q02","module":"项目追问","type":"概念题","title":"墓碑、版本号和消息 ID 分别如何参与恢复？","prompt":"墓碑、版本号和消息 ID 分别如何参与恢复？","promptMarkdown":"墓碑、版本号和消息 ID 分别如何参与恢复？","answer":["message_id 定位事实，版本表达更新次序，墓碑保存已撤回或删除状态防旧内容复活；保留期限需覆盖离线恢复与缓存窗口，不能随便过期。"],"answerMarkdown":"message_id 定位事实，版本表达更新次序，墓碑保存已撤回或删除状态防旧内容复活；保留期限需覆盖离线恢复与缓存窗口，不能随便过期。\n\n**易错点：**墓碑过期会重新打开旧回填窗口。\n\n**下一轮强化：**故障注入报告与已实现能力陈述","pitfalls":["墓碑过期会重新打开旧回填窗口。"],"follow":"故障注入报告与已实现能力陈述","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":12,"sourceQuestion":2,"sourceRoundTitle":"消息撤回、编辑与迟到事件复盘"},{"id":"daily-2026-10-12-r12-q03","module":"项目追问","type":"场景题","title":"客户端离线期间错过撤回，重连仍显示正文，怎样形成证据链？","prompt":"客户端离线期间错过撤回，重连仍显示正文，怎样形成证据链？","promptMarkdown":"客户端离线期间错过撤回，重连仍显示正文，怎样形成证据链？","answer":["关联撤回事务、Outbox、通知发布、客户端断线、补拉响应和本地版本；验证历史接口是否过滤成不存在却未给客户端撤回事实，恢复要明确删除或占位语义。"],"answerMarkdown":"关联撤回事务、Outbox、通知发布、客户端断线、补拉响应和本地版本；验证历史接口是否过滤成不存在却未给客户端撤回事实，恢复要明确删除或占位语义。\n\n**易错点：**查不到不总是撤回证明。\n\n**下一轮强化：**故障注入报告与已实现能力陈述","pitfalls":["查不到不总是撤回证明。"],"follow":"故障注入报告与已实现能力陈述","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":12,"sourceQuestion":3,"sourceRoundTitle":"消息撤回、编辑与迟到事件复盘"},{"id":"daily-2026-10-12-r12-q04","module":"项目追问","type":"代码题","title":"实现只接受更高版本的消息状态，同版本异状态报告冲突。","prompt":"实现只接受更高版本的消息状态，同版本异状态报告冲突。","promptMarkdown":"实现只接受更高版本的消息状态，同版本异状态报告冲突。","answer":["见代码。状态为布尔撤回示意，按版本接受，不自动推断哪些业务转换合法；真实服务器还需权限与状态机。"],"answerMarkdown":"见代码。状态为布尔撤回示意，按版本接受，不自动推断哪些业务转换合法；真实服务器还需权限与状态机。\n\n**易错点：**高版本仍需可信来源与合法状态。\n\n```cpp\n#include <cassert>\n#include <cstdint>\n#include <optional>\nenum class Applied{Updated,Duplicate,Stale,Conflict};\nstruct State{std::uint64_t version;bool recalled;};\nApplied apply(std::optional<State>& current,State next){\n    if(current){\n        if(next.version<current->version)return Applied::Stale;\n        if(next.version==current->version)return next.recalled==current->recalled?Applied::Duplicate:Applied::Conflict;\n    }\n    current=next;return Applied::Updated;\n}\nint main(){std::optional<State> s;assert(apply(s,{1,false})==Applied::Updated);assert(apply(s,{2,true})==Applied::Updated);assert(apply(s,{1,false})==Applied::Stale);assert(s->recalled);assert(apply(s,{2,false})==Applied::Conflict);assert(apply(s,{2,true})==Applied::Duplicate);}\n\n```\n\n**复杂度与边界：**O(1) 时间/空间，单线程内存收敛模型；不包含持久化、权限与业务合法转换验证。\n\n**下一轮强化：**故障注入报告与已实现能力陈述\n\n代码通过 C++17 严格警告编译及所附断言。","pitfalls":["高版本仍需可信来源与合法状态。"],"follow":"故障注入报告与已实现能力陈述","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":12,"sourceQuestion":4,"sourceRoundTitle":"消息撤回、编辑与迟到事件复盘"},{"id":"daily-2026-10-12-r12-q05","module":"项目追问","type":"场景题","title":"如何为撤回与认证撤销设计可复现的故障演练？","prompt":"如何为撤回与认证撤销设计可复现的故障演练？","promptMarkdown":"如何为撤回与认证撤销设计可复现的故障演练？","answer":["建议注入提交后通知前、通知后确认前、旧事件迟到和节点缓存过期；验证幂等、权限、版本不回退、补拉收敛与有限撤销窗口。测试结果与建议设计分开说明。"],"answerMarkdown":"建议注入提交后通知前、通知后确认前、旧事件迟到和节点缓存过期；验证幂等、权限、版本不回退、补拉收敛与有限撤销窗口。测试结果与建议设计分开说明。\n\n**易错点：**测试正常一次不能证明故障恢复。\n\n**下一轮强化：**故障注入报告与已实现能力陈述","pitfalls":["测试正常一次不能证明故障恢复。"],"follow":"故障注入报告与已实现能力陈述","manual":true,"priority":false,"sourceDate":"2026-10-12","sourceRound":12,"sourceQuestion":5,"sourceRoundTitle":"消息撤回、编辑与迟到事件复盘"}];const ids=new Set(window.QUESTION_BANK.map(q=>q.id));for(const q of added){if(!ids.has(q.id)){window.QUESTION_BANK.push(q);ids.add(q.id);}}})();
